<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$userId=(int)current_user()['user_id'];$roadmapId=(int)($_GET['id']??0);
if($roadmapId){$st=$pdo->prepare('SELECT r.*,j.role_name FROM roadmaps r JOIN job_roles j ON j.job_role_id=r.job_role_id WHERE r.roadmap_id=? AND r.user_id=?');$st->execute([$roadmapId,$userId]);$selected=$st->fetch();if(!$selected){flash('Roadmap not found.','error');redirect('roadmap/index.php');}$st=$pdo->prepare('SELECT ri.*,s.skill_name,p.title project_title,lr.title resource_title FROM roadmap_items ri JOIN skills s ON s.skill_id=ri.skill_id LEFT JOIN projects p ON p.project_id=ri.project_id LEFT JOIN learning_resources lr ON lr.resource_id=ri.resource_id WHERE ri.roadmap_id=? ORDER BY ri.sequence_number');$st->execute([$roadmapId]);$items=$st->fetchAll();$total=count($items);$done=count(array_filter($items,fn($x)=>$x['status']==='completed'));$pct=$total?round($done/$total*100):0;
}else{$selected=null;$st=$pdo->prepare('SELECT r.*,j.role_name,COUNT(ri.item_id) total_items,SUM(ri.status=\'completed\') done_items FROM roadmaps r JOIN job_roles j ON j.job_role_id=r.job_role_id LEFT JOIN roadmap_items ri ON ri.roadmap_id=r.roadmap_id WHERE r.user_id=? GROUP BY r.roadmap_id ORDER BY r.created_at DESC');$st->execute([$userId]);$roadmaps=$st->fetchAll();}
$pageTitle='My roadmap';$active='roadmap';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Your next steps</span><h1 class="h1">My roadmap</h1><p>Turn your skill gaps into practical learning and project milestones.</p></div><a class="btn btn-primary" href="<?=h(url('careers/index.php'))?>">New career assessment →</a></div>
<?php if($selected):?><section class="card card-pad"><div class="row-between"><div><span class="pill pill-blue"><?=h($selected['role_name'])?></span><h2 class="h2" style="font-size:22px;margin-top:10px"><?=h($selected['title'])?></h2><p class="muted small">Created <?=date('d M Y',strtotime($selected['created_at']))?><?php if($selected['target_date']):?> · Target <?=date('d M Y',strtotime($selected['target_date']))?><?php endif;?></p></div><span class="pill <?=$selected['status']==='completed'?'pill-green':'pill-blue'?>"><?=h(ucfirst($selected['status']))?></span></div><div class="row-between" style="margin-top:18px"><strong><?=$pct?>% complete</strong><span class="muted tiny"><?=$done?> of <?=$total?> tasks</span></div><div class="progress" style="margin-top:9px"><span style="width:<?=$pct?>%"></span></div><hr class="divider"><div class="roadmap-timeline"><?php foreach($items as $item):?><div class="roadmap-item <?=$item['status']==='completed'?'complete':''?>"><div class="row-between" style="align-items:flex-start"><div><span class="pill <?=$item['priority']==='high'?'pill-red':($item['priority']==='medium'?'pill-amber':'pill-blue')?>"><?=h(ucfirst($item['priority']))?> priority · <?=h(ucwords(str_replace('_',' ',$item['item_type'])))?></span><h4 style="margin-top:7px"><?=h($item['title'])?></h4><p><?=h($item['description'])?></p><div class="tag-row"><span class="tag"><?=h($item['skill_name'])?></span><?php if($item['project_title']):?><span class="tag">Project: <?=h($item['project_title'])?></span><?php elseif($item['resource_title']):?><span class="tag">Resource: <?=h($item['resource_title'])?></span><?php endif;?></div></div></div><form class="task-actions" method="post" action="<?=h(url('roadmap/update.php'))?>" style="margin-top:9px"><?=csrf_field()?><input type="hidden" name="item_id" value="<?=(int)$item['item_id']?>"><select class="task-select" name="status"><option value="not_started" <?=$item['status']==='not_started'?'selected':''?>>Not started</option><option value="in_progress" <?=$item['status']==='in_progress'?'selected':''?>>In progress</option><option value="completed" <?=$item['status']==='completed'?'selected':''?>>Completed</option><option value="skipped" <?=$item['status']==='skipped'?'selected':''?>>Skipped</option></select><button class="btn btn-outline btn-sm">Update</button><?php if($item['project_id']):?><a class="link-arrow" href="<?=h(url('projects/view.php?id='.(int)$item['project_id']))?>">Project details →</a><?php endif;?></form></div><?php endforeach;?></div></section><div style="margin-top:15px"><a class="link-arrow" href="<?=h(url('roadmap/index.php'))?>">← All roadmaps</a></div>
<?php elseif($roadmaps):?><div class="grid grid-2"><?php foreach($roadmaps as $r):$tot=(int)$r['total_items'];$don=(int)$r['done_items'];$p=$tot?round($don/$tot*100):0;?><a class="card card-pad" href="<?=h(url('roadmap/index.php?id='.(int)$r['roadmap_id']))?>"><div class="row-between"><span class="pill pill-blue"><?=h($r['role_name'])?></span><span class="muted tiny"><?=h(ucfirst($r['status']))?></span></div><h3 class="h3" style="margin:13px 0 6px"><?=h($r['title'])?></h3><div class="row-between tiny muted"><span><?=$don?> / <?=$tot?> milestones</span><strong><?=$p?>%</strong></div><div class="progress" style="margin-top:8px"><span style="width:<?=$p?>%"></span></div></a><?php endforeach;?></div>
<?php else:?><div class="card empty-state"><div class="empty-icon">🧭</div><h2>Your roadmap will appear here</h2><p>Choose a career, complete a skill assessment and generate a personalized list of learning and project milestones.</p><a class="btn btn-primary" href="<?=h(url('careers/index.php'))?>">Explore career roles</a></div><?php endif;?></div></main><?php include __DIR__.'/../includes/footer.php';?>
